package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;
/** Public separate polygons: count every side of every polygon; shared-edge chains are a different task. */
public final class GeometricMultiplePatterns {
 private GeometricMultiplePatterns(){}
 public static final String ID="drawMultipleShapePattern";
 public static final Catalog.Skill SKILL=new Catalog.Skill(ID,"도형 배수 무늬와 값 표",6,2,2,"",ID,100,"pairedNumberTableFill,tables","도형을 직접 그리고 도형 수와 변 수의 표 및 곱셈 규칙을 완성한다.");
 public record Givens(int sides,int target,int[] first,int[] shown){}
 public static boolean supports(String id){return ID.equals(id);}
 public static String shape(int n){return switch(n){case 3->"정삼각형";case 4->"정사각형";case 5->"정오각형";case 6->"정육각형";default->throw new IllegalArgumentException("Selected polygon");};}
 public static String instruction(Question q){Givens v=read(q);return v==null?"":shape(v.sides)+" "+v.target+"개를 점을 이어 그리세요. 표의 빈칸 세 개를 채우고 도형 수에서 변 수로 가는 규칙을 설명하세요.";}
 public static Question make(int sides,int target){if(sides<3||sides>6||target<4||target>7)throw new IllegalArgumentException("Selected pattern");StringJoiner xs=new StringJoiner(" | "),ys=new StringJoiner(" | ");for(int i=1;i<=7;i++){xs.add(""+i);ys.add(i<=4?""+(i*sides):"□");}Question q=new Question(ID,"도형: "+shape(sides)+" (한 도형의 변 "+sides+"개)\n그릴 도형 수: "+target+"\n도형 수: "+xs+"\n변 수: "+ys+"\n도형을 따로 그리며 각 도형의 모든 변을 셉니다.","","drawing",""+(5*sides),""+(6*sides),""+(7*sides),"2",""+sides);q.labels=new String[]{"그린 도형","도형 5개","도형 6개","도형 7개","계산","한 도형의 변 수"};q.kind="geometricMultipleComposite";q.stepSupport=false;attach(q);return q;}
 public static Givens read(Question q){if(q==null||!supports(q.skillId)||q.prompt==null)return null;String[] l=q.prompt.split("\n",-1);if(l.length!=5||!l[4].equals("도형을 따로 그리며 각 도형의 모든 변을 셉니다."))return null;Matcher a=Pattern.compile("도형: (정삼각형|정사각형|정오각형|정육각형) [(]한 도형의 변 ([3-6])개[)]").matcher(l[0]);Matcher b=Pattern.compile("그릴 도형 수: ([4-7])").matcher(l[1]);if(!a.matches()||!b.matches())return null;int n=Integer.parseInt(a.group(2)),target=Integer.parseInt(b.group(1));if(!shape(n).equals(a.group(1))||!l[2].startsWith("도형 수: ")||!l[3].startsWith("변 수: "))return null;String[] x=l[2].substring(6).split(Pattern.quote(" | "),-1),y=l[3].substring(5).split(Pattern.quote(" | "),-1);if(x.length!=7||y.length!=7)return null;int[] first=new int[7],shown=new int[7];for(int i=0;i<7;i++){first[i]=i+1;shown[i]=i<4?(i+1)*n:-1;if(!x[i].equals(""+first[i])||!y[i].equals(shown[i]<0?"□":""+shown[i]))return null;}return new Givens(n,target,first,shown);}
 static Question next(Random r,CurriculumLimits l,Map<String,Integer> recent){if(l.wholeMaximum(100)<42)throw new IllegalArgumentException("Selected table bound");return IndexedQuestionSupply.choose(16,i->make(3+i/4,4+i%4),r,l,recent);}
 /** Learner edges use slot:edge; ordering does not change geometry. Every slot is a separate public polygon. */
 public static Set<String> edges(String draft,int sides){if(draft==null||draft.isEmpty())return Set.of();Set<String> out=new TreeSet<>();for(String token:draft.split(",",-1)){if(!token.matches("[0-6]:[0-5]"))return null;int edge=token.charAt(2)-'0';if(edge>=sides||!out.add(token))return null;}return out;}
 public static int completed(String draft,int sides){Set<String> edges=edges(draft,sides);if(edges==null)return -1;int total=0;for(int slot=0;slot<7;slot++){int count=0;for(int e=0;e<sides;e++)if(edges.contains(slot+":"+e))count++;if(count>0&&count<sides)return -1;if(count==sides)total++;}return total;}
 static Checker.Result check(Question q,List<String> a){Givens v=read(q);if(v==null||a==null||a.size()!=6)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"도형과 답 입력 필요");if(a.get(0)==null||a.get(0).isEmpty())return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"점을 이어 도형 그리기 필요");if(completed(a.get(0),v.sides)!=v.target)return new Checker.Result(Checker.Status.WRONG_ANSWER,0,"그린 도형의 개수와 닫힌 변 확인");for(int i=1;i<=3;i++){String value=a.get(i);if(value==null||!value.matches("[0-9]{1,3}"))return new Checker.Result(Checker.Status.INPUT_NEEDED,i,"표의 값 입력 필요");if(Integer.parseInt(value)!=(i+4)*v.sides)return new Checker.Result(Checker.Status.WRONG_ANSWER,i,"이 표의 변 수 확인");}if(a.get(4)==null||!List.of("0","2").contains(a.get(4)))return new Checker.Result(Checker.Status.INPUT_NEEDED,4,"계산 선택 필요");if(!a.get(4).equals("2"))return new Checker.Result(Checker.Status.WRONG_ANSWER,4,"도형 수에서 변 수로 가는 계산 확인");if(a.get(5)==null||!a.get(5).matches("[0-9]{1,3}"))return new Checker.Result(Checker.Status.INPUT_NEEDED,5,"곱할 수 입력 필요");return Integer.parseInt(a.get(5))==v.sides?new Checker.Result(Checker.Status.CORRECT,-1,"도형과 표 및 규칙 확인 완료"):new Checker.Result(Checker.Status.WRONG_ANSWER,5,"한 도형의 변 수 확인");}
 public static void attach(Question q){Givens v=read(q);if(v==null)return;StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion="geometric-multiple-pattern-v1";h.step("한 도형의 변 수를 세세요.","한 도형의 변 수 = ","",""+v.sides);h.step("직접 그려야 할 도형 수를 쓰세요.","그릴 도형 수 = ","",""+v.target);h.step("그릴 도형의 모든 변 수를 구하세요.",v.target+" × "+v.sides+" = ","",""+(v.target*v.sides));for(int i=5;i<=7;i++)h.step("도형 수에 한 도형의 변 수를 곱하세요.",i+" × "+v.sides+" = ","",""+(i*v.sides));Map<String,String> ops=new LinkedHashMap<>();ops.put("0","한 도형의 변 수 더하기");ops.put("2","한 도형의 변 수 곱하기");h.choice("도형 수에서 변 수로 가는 계산을 고르세요.",ops,"2");h.step("도형 수에 곱할 수를 쓰세요.","곱할 수 = ","",""+v.sides);q.studyGuide=h;}
}
